-- The session line below must be the coordinator's own session; written_by is read from it.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (635, '1', $t$ASK 635: hydrogen's output-token limit is raised from 65,536 to 131,072$t$,
  $t$Give hydrogen enough output room that, after its reasoning, it can still write the judgment. In run 42517 hydrogen, as a panel judge, used 65,536 of 65,536 output tokens, 65,533 of them on reasoning, finished "length" and returned no text. Expected effect: when hydrogen judges, the reply ends "stop" with judgment text. Not promised: the record cannot show that 131,072 is enough; hydrogen has filled every limit it was given as a judge. No reasoning setting is touched. (plan rev 1, heading 1, ask635/w4/plan635.md md5 a9fa07cf)$t$,
  'not yet',
  $t$Written by W4 at 05:14 CST 2026-11-25 on the operator's press "Write it" on W4's card, and read back MATCH by W1 (Wall 11971, 11975; audit 42082). One value in one row: model_config seat hydrogen (google/gemini-4-hydrogen) max_tokens 65,536 to 131,072, guarded on the prior value and the api_model; a note line holds the undo value 65536. No engine or child node, no reasoning, temperature or model id, and no other seat changed. NOT YET, because the objective is hydrogen returning a verdict as a judge and no run has been made since the write. W4's search (plan heading 3): Resolve Seats and Panel Build pass max_tokens to the request with floors and no cap; the judge call's timeout is 900 s and the engine stops waiting at 980 s. W4's measure from one call: 65,536 tokens took about 343 s in run 42517, so a full 131,072 would take about 690 s, a guess against a 900 s timeout; a full judge call at the new limit costs about 1.10 dollars. The three legitimate results on a run where hydrogen judges (plan C3): (a) the reply ends "stop" with a stored judgment; (b) the ASK 629 line "returned no text: finish_reason length; output tokens 131,072", which means 131,072 is not enough; (c) a time-out, which means the limit is too high for the time allowed. (b) and (c) go back to the operator. W1's notes on the plan (Wall 11960): N1 Panel Judges Parallel has a 60 s timeout (it only dispatches); N2 the criteria should name the time-out outcome; N3 the operator's quotation was not checked by W1. Plan criterion C2 (an offline replay of Resolve Seats and Panel Build with the new row): W3 found no Wall post that reports it run. NOT SEARCHED by W4: OpenRouter's per-provider endpoint limits. Open: two clean live runs in which hydrogen judges.$t$,
  '11959, 11960, 11971, 11975, 11954',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$(1) Project chat, 04:41 CST 2026-11-25 (message cmsg_017ZQamDMHrS6fqMHnQDVo589SHYu1ca6GGbyLrQ8xVXBq): "let's increase hydrogen tokens." The same message answered 630, 631 and 624 (Wall 11954). (2) W4's write card (cmsg_017ZQamDMHrS6fqMHnQDVo58KVszvhk32wAUdh8kGQne16, "Raise hydrogen's output limit from 65,536 to 131,072 tokens?"): he pressed "Write it" at 05:14 CST 2026-11-25. The card is from W4's thread note to W3 of 05:19 CST; W3 did not read it. There was no build card: nothing was built.$t$::text),
  $j${"answer": "Write it", "question": "Raise hydrogen's output limit from 65,536 to 131,072 tokens?", "thread": "W4", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo58KVszvhk32wAUdh8kGQne16", "press_time": "05:14 CST 2026-11-25", "instruction": {"where": "project chat", "message_id": "cmsg_017ZQamDMHrS6fqMHnQDVo589SHYu1ca6GGbyLrQ8xVXBq", "words": "let's increase hydrogen tokens.", "time": "04:41 CST 2026-11-25"}, "source": "W4's thread note to W3, 05:19 CST 2026-11-25; Wall 11971; audit 42082. Card not read by W3."}$j$::jsonb,
  'W4',
  $j${"md5": "a9fa07cf", "path": "ask635/w4/plan635.md", "note": "plan rev 1; rev 0 (803c9032, commit a7c022ab) graded PASS WITH N1 to N3 by W1 (Wall 11960, commit 28082b0c); rev 1 applies them by its own first line. No Wall grade of rev 1 by itself was found by W3.", "source": "md5sum by W3; Wall 11959, 11960"}$j$::jsonb,
  $j$[]$j$::jsonb,
  $j${"database": "UPDATE model_config SET max_tokens=65536 WHERE seat='hydrogen' AND max_tokens=131072 (as written in audit_log row 42082; the row's note line holds the undo value)", "engine": "not written; nothing to revert", "child": "not written; nothing to revert", "rehearsed": "not stated in the Wall posts W3 read", "source": "audit 42082; Wall 11971"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS WITH N1 to N3 (plan rev 0)", "wall_id": 11960, "md5_graded": "803c9032", "verdict_norm": "PASS", "source": "Wall 11960; fairjudge/w1/g635/grade_plan635.md (commit 28082b0c)"}]$j$::jsonb,
  ARRAY[]::text[], '[42082]'::jsonb,
  $j$[{"kind": "table row", "name": "model_config, seat hydrogen (google/gemini-4-hydrogen)", "before": "max_tokens 65536", "after": "max_tokens 131072, active; api_model, family and active unchanged; a note line holds the undo value and \"reasoning untouched\" (W1's readback, Wall 11975; read by W3 at 05:18 CST: 131072, active)"}]$j$::jsonb,
  $j$[{"name": "Fetch back of the row", "result": "131,072, active (W4, Wall 11971); MATCH by W1 with the other seats unchanged (Wall 11975)", "source": "Wall 11971, 11975"}, {"name": "Plan criterion C2 (offline replay of Resolve Seats and Panel Build on the 42517 inputs with the new row)", "result": "no Wall post read by W3 reports it run", "source": "plan635.md heading 4"}, {"name": "NOT RUN", "result": "any call to hydrogen at 131,072; the plan offered one paid replay of the 42517 hydrogen call as an option, and W3 knows of none made", "source": "Wall 11959"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "MATCH (model_config hydrogen max_tokens 131072; api_model, active and family unchanged; the notes give undo 65536 and \"reasoning untouched\"; the other seats unchanged)", "wall_id": 11975, "source": "Wall 11975 (commit f8704548)"}]$j$::jsonb,
  $j${"case": "NO RUN YET.", "runs": [], "mark_for_the_next_run": "on a run where hydrogen judges: (a) its reply ends \"stop\" with a stored judgment, a clean run; (b) the detail \"returned no text: finish_reason length; output tokens 131,072\", which means the limit is not enough; (c) a time-out error on its seat, which means the limit is too high for the time allowed. Report (b) or (c) to the operator. As a debater hydrogen stayed under the old limit in run 42528, so a debater-only run does not exercise this.", "not_shown": "that hydrogen returns a verdict at 131,072; the time a full reply takes.", "source": "plan635.md headings 1 and 4; Wall 11959, 11960"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "NOT WRITTEN. Two pairs on part 10.0 (ALTERNATE HYDROGEN: the row's max_tokens; the measured risk) in manual1123/w3/a629_635/em_pairs_629_635_draft1.json (833903a5), graded PASS WITH N1 by W1 (Wall 11975; N1 is on the part 16.0 pair of ASK 629). The write needs the operator's card."}$j$::jsonb,
  'read back', $j$[11959, 11960, 11971, 11975, 11954]$j$::jsonb)
RETURNING id)
